  "backend/landungen/FRA.yaml": "# Eigene Frankfurt-Strecke mit milden Kurven und dynamischem Flugverkehr.\ncode: FRA\nbezeichnung: Frankfurt\nmodule: null\nfaehigkeitskarten: 0\nschwierigkeit: 1\nlaenge: 7\nneuwurf_hoehen: [6000, 2000]\n\n# Entfernung 6 bis 0 (Flughafen).\n# Format: <initiale Flugzeuge> <schwarze Verkehrswürfel> <kurven_min> <kurven_max>\n# Die schwarzen Würfel werden vor JEDER Runde am aktuellen Feld geworfen,\n# auch wenn man dort stehen bleibt. Seiten: 2, 3, 3, 4, 4, 5.\n# Wie beim Funk zählt das aktuelle Feld als 1; Ziele außerhalb entfallen.\nflugzeuge_wuerfel_kurven_min_max:\n- 0 1 -2 2\n- 1 0 -1 2\n- 1 2 -1 1\n- 0 0 -2 1\n- 1 1 -1 2\n- 1 0 -2 2\n- 0 0 -2 2\n",
  "backend/landungen/LHR.yaml": "# FLUGHAFEN INFORMATIONEN\ncode: LHR\nbezeichnung: London Heathrow\n\n# MODULE\nmodule: null\nfaehigkeitskarten: 0\n\n# SCHWIERIGKEIT UND LAENGE\nschwierigkeit: 0\nlaenge: 5\nneuwurf_hoehen: [6000, 2000]\n\n# FLUGZEUGE UND KURVEN\n#\n# Ein Eintrag pro Feld der Entfernungsleiste, von \"am weitesten weg\"\n# (Entfernung 4) bis zum Flughafen (Entfernung 0).\n# Format je Zeile: \"<initiale Flugzeuge> <flugzeugwuerfel> <kurven_min> <kurven_max>\"\n#\n# ANNAHME: Die Anzahl der Flugzeuge pro Feld ist NICHT im Regelheft als\n# Zahl angegeben - im echten Spiel steht sie auf der bedruckten\n# Entfernungsleiste (Icons pro Feld). Das Aufbau-Kapitel (S.3) nennt nur\n# die Gesamtzahl \"12 Flugzeuge (9 auf der Leiste, 3 bleiben übrig)\" als\n# allgemeine Materialübersicht für alle Flughäfen. Die folgende\n# Verteilung (Summe = 9) ist daher ein PLATZHALTER, den ich anhand der\n# Gesamtzahl geraten habe. Bitte anhand des echten MUC-Leiste-Bauteils\n# korrigieren! (Der Text erwähnte früher versehentlich MUC.)\n#\n# \"flugzeugwuerfel\", \"kurven_min\" und \"kurven_max\" kommen im Basis-\n# Regelheft nicht vor (siehe Hinweis in landung.py) und werden aktuell\n# von der Engine nicht ausgewertet - Platzhalterwerte.\nflugzeuge_wuerfel_kurven_min_max:\n- 0 0 -1 2\n- 1 0 -0 2\n- 2 0 -2 2\n- 2 0 -2 2\n- 1 0 -2 2\n",
